public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        while (T-- > 0) {
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }
            int count = 0;
            for (int i = 0; i < n; i++) {
                if (a[i] <= k) {
                    count++;
                    k -= a[i];
                }
            }
            System.out.println(count);
        }
    }
}

